package main

import (
	"fmt"
	"slices"
	"strings"
	"text/template"
)

func generateHelpers(d APIDescription) error {
	helpers := strings.Builder{}
	helpers.WriteString(`
// THIS FILE IS AUTOGENERATED. DO NOT EDIT.
// Regen by running 'go generate' in the repo root.

package gotgbot
`)

	for _, tgTypeName := range orderedTgTypes(d) {
		tgType := d.Types[tgTypeName]

		helper, err := generateTypeHelperDef(d, tgType)
		if err != nil {
			return fmt.Errorf("failed to generate type helpers for %s: %w", tgType.Name, err)
		}
		if helper != "" {
			helpers.WriteString(helper)
		}

		richWalkHelper := generateRichWalkHelperDef(d, tgType)
		if richWalkHelper != "" {
			helpers.WriteString(richWalkHelper)
		}
	}

	return writeGenToFile(helpers, "gen_helpers.go")
}

type helperData struct {
	newName     string
	method      MethodDescription
	fields      map[string]string
	returnTypes []string
	defArgList  []string
	callArgList []string
	opts        string
}

func (d helperData) docs() string {
	return "\n// " + d.newName + " is a helper method for Bot." + strings.Title(d.method.Name) + "."
}

func getHelpers(d APIDescription, typeName string, typeFields []Field) ([]helperData, error) {
	receiver := receiver(typeName)
	if typeName == "InaccessibleMessage" {
		typeName = tgTypeMessage
	}

	var methods []helperData
	for _, methodName := range orderedMethods(d) {

		tgMethod := d.Methods[methodName]

		// Get list of fields which match the method types
		fieldMatches := getFieldsTypeMatches(typeName, typeFields, tgMethod.Fields)
		if len(fieldMatches) == 0 {
			continue
		}

		newMethodName, ok, err := getMethodFieldsSubtypeMatches(d, typeName, typeFields, tgMethod, fieldMatches)
		if err != nil {
			return nil, err
		}
		if !ok {
			continue
		}

		ret, err := tgMethod.GetReturnTypes(d)
		if err != nil {
			return nil, fmt.Errorf("failed to get return type for %s: %w", tgMethod.Name, err)
		}

		funcCallArgList, funcDefArgList, optsContent, err := generateHelperArguments(d, tgMethod, receiver, fieldMatches)
		if err != nil {
			return nil, err
		}

		methods = append(methods, helperData{
			newName:     newMethodName,
			method:      tgMethod,
			fields:      fieldMatches,
			returnTypes: ret,
			callArgList: funcCallArgList,
			defArgList:  funcDefArgList,
			opts:        optsContent,
		})
	}

	return methods, nil
}

func generateTypeHelperDef(d APIDescription, tgType TypeDescription) (string, error) {
	if tgType.Name == tgTypeFile {
		return "", nil
	}
	if len(tgType.Subtypes) != 0 {
		// TODO: Generate common list of methods for all the child types
		return "", nil
	}

	helpers, err := getHelpers(d, tgType.Name, tgType.Fields)
	if err != nil {
		return "", err
	}

	helperDef := strings.Builder{}
	for _, helper := range helpers {
		helperDef.WriteString(helper.docs())

		err = helperFuncTmpl.Execute(&helperDef, helperFuncData{
			Receiver:     tgType.receiverName(),
			TypeName:     tgType.Name,
			HelperName:   helper.newName,
			ReturnType:   strings.Join(helper.returnTypes, ", "),
			FuncDefArgs:  strings.Join(helper.defArgList, ", "),
			Contents:     helper.opts,
			OptsName:     helper.method.optsName(),
			MethodName:   strings.Title(helper.method.Name),
			FuncCallArgs: strings.Join(helper.callArgList, ", "),
		})
		if err != nil {
			return "", fmt.Errorf("failed to execute template to generate %s helper method on %s: %w", helper.newName, tgType.Name, err)
		}
	}

	if tgType.Name == tgTypeMessage {
		// Implement reply helpers for all message types
		for _, method := range orderedMethods(d) {
			tgMethod := d.Methods[method]

			if tgMethod.hasField("reply_parameters") {
				returns, err := tgMethod.GetReturnTypes(d)
				if err != nil {
					return "", fmt.Errorf("failed to get return type for %s: %w", tgMethod.Name, err)
				}

				funcCall, funcDef, _, err := generateHelperArguments(d, tgMethod, tgType.receiverName(), map[string]string{"chat_id": "chat.Id"})
				if err != nil {
					return "", fmt.Errorf("failed to generate helper arguments for %s: %w", tgMethod.Name, err)
				}

				err = helperReplyFuncTmpl.Execute(&helperDef, helperReplyFuncData{
					ReceiverName: tgType.receiverName(),
					HelperName:   "Reply" + strings.Title(strings.ReplaceAll(method, "send", "")),
					ReturnType:   strings.Join(returns, ", "),
					FuncDefArgs:  strings.Join(funcDef, ", "),
					OptsName:     tgMethod.optsName(),
					MethodName:   strings.Title(tgMethod.Name),
					FuncCallArgs: strings.Join(funcCall, ", "),
				})
				if err != nil {
					return "", fmt.Errorf("failed to execute template to generate %s helper method on %s: %w", method, tgType.Name, err)
				}
			}
		}
	}

	return helperDef.String(), nil
}

func hasFromChat(tgMethod MethodDescription) bool {
	hasFromChat := false

	for _, x := range tgMethod.Fields {
		if x.Name == "from_chat_id" {
			hasFromChat = true
			break
		}
	}
	return hasFromChat
}

func generateHelperArguments(d APIDescription, tgMethod MethodDescription, receiverName string, fields map[string]string) ([]string, []string, string, error) {
	var funcCallArgList []string
	optsContent := strings.Builder{}
	funcDefArgList := []string{"b *Bot"}
	hasOpts := false

	for _, mf := range tgMethod.Fields {
		hasOpts = hasOpts || !mf.Required

		prefType, err := mf.getPreferredType(d)
		if err != nil {
			return nil, nil, "", fmt.Errorf("failed to get preferred type for field %s of %s: %w", mf.Name, tgMethod.Name, err)
		}

		if fName, ok := fields[mf.Name]; ok {
			if !mf.Required {
				defaultValue := getDefaultTypeVal(d, prefType)
				optsContent.WriteString("\n	if opts." + snakeToTitle(mf.Name) + " == " + defaultValue + " {")
				if isPointer(prefType) {
					optsContent.WriteString("\n		opts." + snakeToTitle(mf.Name) + " = &" + receiverName + "." + snakeToTitle(fName))
				} else {
					optsContent.WriteString("\n		opts." + snakeToTitle(mf.Name) + " = " + receiverName + "." + snakeToTitle(fName))
				}
				optsContent.WriteString("\n	}")
				continue
			}

			funcCallArgList = append(funcCallArgList, receiverName+"."+snakeToTitle(fName))
			continue
		}

		if !mf.Required {
			continue
		}

		funcDefArgList = append(funcDefArgList, snakeToCamel(mf.Name)+" "+prefType)
		funcCallArgList = append(funcCallArgList, snakeToCamel(mf.Name))
	}

	funcDefArgList = append(funcDefArgList, "opts *"+tgMethod.optsName())
	funcCallArgList = append(funcCallArgList, "opts")

	return funcCallArgList, funcDefArgList, optsContent.String(), nil
}

func getMethodFieldsSubtypeMatches(d APIDescription, typeName string, typeFields []Field, tgMethod MethodDescription, fields map[string]string) (string, bool, error) {
	newMethodName := strings.Replace(tgMethod.Name, typeName, "", 1)
	fromChat := hasFromChat(tgMethod)

	for _, f := range typeFields {
		if f.Name == "reply_to_message" {
			// this subfield just causes confusion; we always want the message_id
			continue
		}

		for _, mf := range tgMethod.Fields {
			prefType, err := f.getPreferredType(d)
			if err != nil {
				return "", false, fmt.Errorf("failed to get preferred type for field %s of %s: %w", mf.Name, tgMethod.Name, err)
			}

			if isTgType(d, prefType) && f.Name+"_id" == mf.Name {
				newMethodName = strings.ReplaceAll(newMethodName, prefType, "")

				if fromChat && mf.Name == "chat_id" {
					fields["from_chat_id"] = f.Name + ".Id"
				} else {
					fields[mf.Name] = f.Name + ".Id" // Note: maybe not just assume ID field exists?
				}
			}
		}
	}
	return strings.Title(newMethodName), newMethodName != tgMethod.Name, nil
}

func getFieldsTypeMatches(typeName string, typeFields []Field, methodFields []Field) map[string]string {
	fields := map[string]string{}
	snakeTypeNameId := titleToSnake(typeName) + "_id"

	for _, f := range methodFields {
		if f.Name == snakeTypeNameId || f.Name == "id" {
			fields[snakeTypeNameId] = findIdField(typeFields, f.Name)
		}
	}
	return fields
}

func findIdField(typeFields []Field, methodFieldName string) string {
	// And iterate over all the type fields, to see if any match the method field name.
	for _, f := range typeFields {
		if methodFieldName == f.Name {
			return methodFieldName
		}
	}
	return "id" // we default to "id" if nothing else matches
}

var helperFuncTmpl = template.Must(template.New("helperFunc").Parse(helperFunc))

type helperFuncData struct {
	Receiver     string
	TypeName     string
	HelperName   string
	ReturnType   string
	FuncDefArgs  string
	Contents     string
	OptsName     string
	MethodName   string
	FuncCallArgs string
}

const helperFunc = `
func ({{.Receiver}} {{.TypeName}}) {{.HelperName}}({{.FuncDefArgs}}) ({{.ReturnType}}, error) {
	{{- if .Contents}}
		if opts == nil {
			opts = &{{.OptsName}}{}
		}
		{{.Contents}}

	{{end}}
	return b.{{.MethodName}}({{.FuncCallArgs}})
}
`

var helperReplyFuncTmpl = template.Must(template.New("helperReplyFunc").Parse(helperReplyFunc))

type helperReplyFuncData struct {
	ReceiverName string
	HelperName   string
	ReturnType   string
	FuncDefArgs  string
	OptsName     string
	MethodName   string
	FuncCallArgs string
}

const helperReplyFunc = `
// {{.HelperName}} is a shortcut to reply to the current message with a specific message type.
func ({{.ReceiverName}} Message) {{.HelperName}}({{.FuncDefArgs}}) ({{.ReturnType}}, error) {
	if opts == nil {
		opts = &{{.OptsName}}{}
	}

	opts.ReplyParameters = opts.ReplyParameters.replyTo({{.ReceiverName}})

	return b.{{.MethodName}}({{.FuncCallArgs}})
}
`

// generateRichWalkHelperDef generates Children()/RichTextChildren()/RichBlockChildren()
// on any concrete type that is a RichText or RichBlock subtype, or that embeds rich
// fields (e.g. RichBlockCaption, RichBlockTableCell).
func generateRichWalkHelperDef(d APIDescription, tgType TypeDescription) string {
	// Only concrete types - interfaces are handled via generateGenericInterfaceType.
	if len(tgType.Subtypes) != 0 || tgType.Href == internalTypeRef {
		return ""
	}

	// Determine which rich interface(s) this type belongs to.
	var parentRichType string
	for _, parent := range tgType.SubtypeOf {
		if parent == tgTypeRichText || parent == tgTypeRichBlock {
			parentRichType = parent
			break
		}
	}

	// Also handle embedded-rich types that aren't direct interface subtypes
	// (e.g. RichBlockCaption, RichBlockTableCell, RichBlockListItem).
	hasAnyRichField := false
	for _, f := range tgType.Fields {
		_, fType := typeOfTgArray(f.Types[0])
		if isRichTextType(fType) {
			hasAnyRichField = true
			break
		}
	}

	if parentRichType == "" && !hasAnyRichField {
		return ""
	}

	// Separate rich fields by which interface they belong to.
	type richField struct {
		goName      string
		isArray     bool
		required    bool
		fieldParent string // "RichText" or "RichBlock"
	}
	var richFields []richField
	for _, f := range tgType.Fields {
		isArr, fType := typeOfTgArray(f.Types[0])
		if !isRichTextType(fType) {
			continue
		}

		var fp string
		if strings.HasPrefix(fType, tgTypeRichBlock) {
			if fieldType, ok := d.Types[fType]; ok && slices.Contains(fieldType.SubtypeOf, tgTypeRichBlock) {
				fp = tgTypeRichBlock
			}
			// else: RichBlock-prefixed struct that isn't a RichBlock subtype
			// (Caption, TableCell, ListItem) - skip, handled separately
		} else if strings.HasPrefix(fType, tgTypeRichText) {
			if fieldType, ok := d.Types[fType]; ok && slices.Contains(fieldType.SubtypeOf, tgTypeRichText) {
				fp = tgTypeRichText
			} else if fType == tgTypeRichText {
				// The interface itself (field type is exactly "RichText")
				fp = tgTypeRichText
			}
			// else: RichText-prefixed struct that isn't a RichText subtype - skip
		}

		if fp == "" {
			continue // not a direct interface member, skip
		}

		richFields = append(richFields, richField{
			goName:      snakeToTitle(f.Name),
			isArray:     isArr,
			required:    f.Required,
			fieldParent: fp,
		})
	}

	bd := strings.Builder{}

	// Helper to emit one Children-style method.
	emitMethod := func(receiverType, methodName, returnType string, fields []richField) {
		if len(fields) == 0 {
			bd.WriteString(fmt.Sprintf("\nfunc (v %s) %s() []%s {\n\treturn nil\n}\n",
				receiverType, methodName, returnType))
			return
		}

		bd.WriteString(fmt.Sprintf("\nfunc (v %s) %s() []%s {\n", receiverType, methodName, returnType))

		if len(fields) == 1 {
			f := fields[0]
			if f.isArray {
				if !f.required {
					bd.WriteString(fmt.Sprintf("\tif len(v.%s) == 0 {\n\t\treturn nil\n\t}\n", f.goName))
				}
				bd.WriteString(fmt.Sprintf("\tout := make([]%s, len(v.%s))\n", returnType, f.goName))
				bd.WriteString(fmt.Sprintf("\tfor i, c := range v.%s {\n\t\tout[i] = c\n\t}\n", f.goName))
				bd.WriteString("\treturn out\n")
			} else {
				if !f.required {
					bd.WriteString(fmt.Sprintf("\tif v.%s == nil {\n\t\treturn nil\n\t}\n", f.goName))
				}
				bd.WriteString(fmt.Sprintf("\treturn []%s{v.%s}\n", returnType, f.goName))
			}
		} else {
			bd.WriteString(fmt.Sprintf("\tvar out []%s\n", returnType))
			for _, f := range fields {
				if f.isArray {
					if !f.required {
						bd.WriteString(fmt.Sprintf("\tfor _, c := range v.%s {\n\t\tout = append(out, c)\n\t}\n", f.goName))
					} else {
						bd.WriteString(fmt.Sprintf("\tfor _, c := range v.%s {\n\t\tout = append(out, c)\n\t}\n", f.goName))
					}
				} else {
					if !f.required {
						bd.WriteString(fmt.Sprintf("\tif v.%s != nil {\n\t\tout = append(out, v.%s)\n\t}\n", f.goName, f.goName))
					} else {
						bd.WriteString(fmt.Sprintf("\tout = append(out, v.%s)\n", f.goName))
					}
				}
			}
			bd.WriteString("\treturn out\n")
		}
		bd.WriteString("}\n")
	}

	switch parentRichType {
	case tgTypeRichText:
		// RichText subtypes: one Children() returning []RichText.
		// All their rich fields must be RichText (the API doesn't mix Text/Block fields).
		emitMethod(tgType.Name, "Children", tgTypeRichText, richFields)

	case tgTypeRichBlock:
		// RichBlock subtypes: two methods - split fields by which interface they satisfy.
		var textFields, blockFields []richField
		for _, f := range richFields {
			if f.fieldParent == tgTypeRichText {
				textFields = append(textFields, f)
			} else {
				blockFields = append(blockFields, f)
			}
		}
		emitMethod(tgType.Name, "RichTextChildren", tgTypeRichText, textFields)
		emitMethod(tgType.Name, "RichBlockChildren", tgTypeRichBlock, blockFields)

	default:
		// Embedded-rich struct (e.g. RichBlockCaption, RichBlockTableCell, RichBlockListItem).
		// Not a direct interface subtype, but has RichText/RichBlock fields - emit both.
		var textFields, blockFields []richField
		for _, f := range richFields {
			if f.fieldParent == tgTypeRichText {
				textFields = append(textFields, f)
			} else {
				blockFields = append(blockFields, f)
			}
		}
		if len(textFields) > 0 {
			emitMethod(tgType.Name, "RichTextChildren", tgTypeRichText, textFields)
		}
		if len(blockFields) > 0 {
			emitMethod(tgType.Name, "RichBlockChildren", tgTypeRichBlock, blockFields)
		}
	}

	return bd.String()
}
